 page.goto(os.environ.get('AFRA_TEST_URL','http://127.0.0.1:5173'));page.get_by_label('ایمیل',exact=True).fill(email);page.get_by_label('گذرواژه',exact=True).fill(secret);page.get_by_role('button',name='ورود به سامانه',exact=True).click();page.get_by_role('heading',name='نمای کلی',exact=True).wait_for();page.get_by_role('menuitem',name='تست‌ها و نیازمندی‌ها',exact=False).click()
