with sync_playwright() as p:
 browser=p.chromium.launch(executable_path='/usr/bin/chromium',headless=True,args=['--no-sandbox','--disable-dev-shm-usage']);page=browser.new_page(viewport={'width':1440,'height':1050},timezone_id='Asia/Tehran');watch(page)
 try:
  login(page,os.environ['AFRA_TEST_EMAIL']);reqs(page);page.get_by_role('button',name='نیازمندی جدید',exact=True).click();dialog=page.get_by_role('dialog');dialog.get_by_label('عنوان',exact=True).fill(title);dialog.get_by_label('شرح نیازمندی',exact=True).fill('حساب فعال با اطلاعات معتبر بتواند وارد شود.');dialog.get_by_label('معیارهای پذیرش قابل مشاهده',exact=True).fill('پس از ورود معتبر، نمای کلی پروژه نمایش داده شود.');dialog.get_by_label('دلیل تغییر',exact=True).fill('ثبت نیازمندی آموزشی برای بررسی گردش نسخه‌ها.');dialog.get_by_role('button',name='ذخیره',exact=True).click();dialog.wait_for(state='hidden');row=page.get_by_role('row').filter(has_text=title);row.wait_for();page.get_by_role('menuitem',name='تست کیس‌ها',exact=True).click();page.get_by_role('button',name='افزودن',exact=False).click();dialog=page.get_by_role('dialog');dialog.get_by_label('عنوان تست کیس',exact=True).fill(case_title);dialog.get_by_label('کاری که باید انجام شود',exact=True).fill('با حساب معتبر وارد شوید.');dialog.get_by_label('نتیجه مورد انتظار همین مورد',exact=True).fill('نمای کلی پروژه نمایش داده شود.');control=dialog.get_by_label('نیازمندی‌های مرتبط و نسخه آن‌ها',exact=False);control.fill(title);page.locator('.ant-select-dropdown:visible .ant-select-item-option-content').filter(has_text=title).click();dialog.get_by_role('button',name='ذخیره',exact=True).click();dialog.wait_for(state='hidden');reqs(page);row=page.get_by_role('row').filter(has_text=title);row.get_by_role('button',name='ویرایش',exact=True).click();dialog=page.get_by_role('dialog');expect(dialog.get_by_label('عنوان',exact=True)).to_have_value(title);dialog.get_by_label('معیارهای پذیرش قابل مشاهده',exact=True).fill('پس از ورود معتبر، نام فرد و نمای کلی پروژه نمایش داده شود.');dialog.get_by_label('دلیل تغییر',exact=True).fill('افزودن نمایش نام به معیار پذیرش آموزشی.');dialog.get_by_role('button',name='ذخیره',exact=True).click();dialog.wait_for(state='hidden');row.get_by_role('button',name='جزئیات و پوشش',exact=True).click();dialog=page.get_by_role('dialog',name=title,exact=True);dialog.get_by_text('نیازمند بررسی تغییر',exact=True).wait_for();page.screenshot(path='/tmp/afra-requirement-impact.png');dialog.get_by_role('tab',name='تاریخچه نسخه‌ها',exact=True).click();expect(dialog.get_by_role('listitem')).to_have_count(2)
  reviewer=browser.new_page(viewport={'width':1440,'height':1050});watch(reviewer);login(reviewer,os.environ['AFRA_REVIEWER_EMAIL']);reqs(reviewer);reviewer.get_by_role('row').filter(has_text=title).get_by_role('button',name='جزئیات و پوشش',exact=True).click();dialog=reviewer.get_by_role('dialog',name=title,exact=True);dialog.get_by_role('button',name='تأیید سازگاری',exact=True).click();dialog.get_by_label('دلیل سازگاری همین نسخه تست با همین نسخه نیازمندی',exact=True).fill('بازبین مستقل بررسی کرد؛ گام فعلی انتظار تازه را پوشش می‌دهد.');dialog.get_by_role('button',name='تأیید سازگاری؛ بدون ثبت Pass',exact=True).click();dialog.get_by_text('برنامه‌ریزی نشده',exact=True).wait_for();reviewer.set_viewport_size({'width':390,'height':844});reviewer.wait_for_timeout(350);assert reviewer.evaluate('document.documentElement.scrollWidth<=innerWidth+1');reviewer.screenshot(path='/tmp/afra-requirement-mobile.png');assert not errors and not failed;print(json.dumps({'page_errors':errors,'failed_api_requests':failed},ensure_ascii=False))
 except Exception:
  page.screenshot(path='/tmp/afra-requirement-debug.png');print(json.dumps({'page_errors':errors,'failed_api_requests':failed},ensure_ascii=False));raise
 finally:browser.close()
